local M={}
function M.new(root)
    local language,nextPoll=0,0
    return {
        update=function(now)
            if now<nextPoll then return end;nextPoll=now+1
            local f=io.open(root.."language.txt","r");if not f then return end
            local value=f:read(16);f:close();local n=tonumber(value)
            if n and n%1==0 and n>=0 and n<=4 then language=n end
        end,
        translate=function(text)
            local row=texts[text];return row and row[language+1] or text
        end,
    }
end
return M
